"""Original homogeneous-kernel norm and nonattainment candidates.
Explicit finite shape domain; independent mathematical review is required.
"""
from pathlib import Path
import json,sys
import sympy as s
P=Path(__file__).resolve().parent
sys.path.insert(0,str(P/'frozen'))
from common import tex as L,prose as T,package,eq,truth,digest
FID='quality-integration-olympiad-homogeneous-Hilbert-kernel-norm'
SHAPES=[s.Rational(j,2) for j in range(1,15)]
META={'familyId':FID,'topic':'integration','difficulty':'olympiad','finiteInstanceIndices':list(range(14)),'relatedIdeaGroupId':'homogeneous-integral-kernel-sharp-L2-norm','primaryTechnique':'logarithmic-convolution-and-translation-defect','difficultyRationale':'Discover the weight or logarithmic isometry that turns a homogeneous double integral into convolution. Prove a global bound, construct a sharp sequence, and distinguish nonattainment in the infinite-measure space.','nearestNeighbor':'The existing finite moment projection and capped-density problems have attainable extremizers. Here translation invariance after a logarithmic change of variables prevents any nonzero L2 extremizer; long logarithmic plateaus establish sharpness. Series Hilbert/Hardy operators are related methods, not the same continuous shape-parametrized task.','prerequisites':['change of variables','Cauchy–Schwarz','Tonelli theorem','dominated convergence'],'sourceRecordIds':[],'constructorVersion':'quality-homogeneous-Hilbert-kernel-v1'}
def catalog():return [META]
def build(fid,index):
 if fid!=FID or type(index)is not int or index not in range(14):raise ValueError('Outside finite kernel-shape domain')
 p=SHAPES[index];C=s.simplify(s.gamma(p/2)**2/s.gamma(p));wrong=2*C if index%2==0 else C/2
 combos=[(C,False),(wrong,False),(C,True),(wrong,True)]
 def display(value,attained):return r'\left('+L(value)+r',\ \textnormal{'+('yes' if attained else 'no')+r'}\right)'
 opts=[(str(value)+';'+str(attained),display(value,attained),'correct' if j==0 else 'Count both logarithmic orientations twice' if j==1 and index%2==0 else 'Keep only one side of the logarithmic convolution kernel' if j==1 else 'Treat the nonintegrable constant in logarithmic coordinates as an admissible extremizer' if j==2 else 'Combine the kernel normalization and attainment mistakes') for j,(value,attained) in enumerate(combos)]
 kernel=r'\frac{(xy)^{'+L((p-1)/2)+r'}}{(x+y)^{'+L(p)+r'}}'
 if p==1:kernel=r'\frac1{x+y}'
 Q=T('Let f range over nonnegative measurable real functions with the stated finite nonzero squared integral. Find the ordered pair consisting of the smallest constant C valid for every such f and yes or no to whether equality holds for any such f.')+r'\quad0<\int_0^\infty f(x)^2\,\mathrm dx<\infty,\qquad\int_0^\infty\int_0^\infty '+kernel+r'f(x)f(y)\,\mathrm dx\,\mathrm dy\le C\int_0^\infty f(x)^2\,\mathrm dx.'
 if C.has(s.gamma):Q+=r'\quad\Gamma(z)=\int_0^\infty t^{z-1}e^{-t}\,\mathrm dt\quad(z>0).'
 steps=[T('Denote the double integral in the question by J. Define the Gamma function used below.'),r'J(f)=\int_0^\infty\int_0^\infty '+kernel+r'f(x)f(y)\,\mathrm dx\,\mathrm dy,\qquad\Gamma(z)=\int_0^\infty t^{z-1}e^{-t}\,\mathrm dt\quad(z>0).',T('Use logarithmic coordinates to expose the scale invariance. Define the positive shape parameter and the isometric change of unknown.'),r'p='+L(p)+r',\quad x=e^u,\quad g(u)=e^{u/2}f(e^u),\qquad\int_0^\infty f(x)^2\,\mathrm dx=\int_{\mathbb R}g(u)^2\,\mathrm du.',T('All original factors, including both Jacobians, combine into a kernel depending only on the difference of the logarithmic coordinates.'),r'k_p(t)=(2\cosh(t/2))^{-p}>0,\qquad J(f)=\int_{\mathbb R}k_p(t)\left(\int_{\mathbb R}g(u)g(u-t)\,\mathrm du\right)\mathrm dt.',T('Translation preserves the squared integral. Cauchy–Schwarz bounds each inner correlation by that integral. Tonelli applies because the functions and kernel are nonnegative.'),r'J(f)\le C_p\int_{\mathbb R}g(u)^2\,\mathrm du,\qquad C_p=\int_{\mathbb R}k_p(t)\,\mathrm dt.',T('With the exponential substitution, the kernel mass is an Euler beta integral. Both endpoints converge because the shape parameter is positive.'),r'z=e^t,\qquad C_p=\int_0^\infty\frac{z^{p/2-1}}{(1+z)^p}\,\mathrm dz=\frac{\Gamma(p/2)^2}{\Gamma(p)}='+L(C)+r'.',T('To prove this constant cannot be lowered, use normalized indicators of longer and longer intervals in logarithmic coordinates.'),r'g_L(u)=\frac{\mathbf1_{[-L,L]}(u)}{\sqrt{2L}},\quad\int_{\mathbb R}g_L^2=1,\quad\int_{\mathbb R}g_L(u)g_L(u-t)\,\mathrm du=\max\!\left(1-\frac{|t|}{2L},0\right).',r'f_L(x)=\frac{\mathbf1_{[e^{-L},e^L]}(x)}{\sqrt{2Lx}},\qquad J(f_L)\longrightarrow C_p\quad(L\to\infty).',T('Dominated convergence applies with the integrable kernel as majorant. These are admissible nonzero functions for every positive L, so the bound is sharp.'),T('Finally, equality would make every translation defect vanish for almost every shift. The following nonnegative identity makes the obstruction explicit.'),r'C_p\int_{\mathbb R}g^2-J(f)=\frac12\int_{\mathbb R}k_p(t)\int_{\mathbb R}(g(u)-g(u-t))^2\,\mathrm du\,\mathrm dt.',T('Translations are continuous in the L2 norm. Since the kernel is strictly positive, equality forces translation invariance for every shift. A translation-invariant L2 function on the real line is constant almost everywhere, and the only such square-integrable constant is zero. This contradicts the required nonzero squared integral.'),opts[0][1]]
 X,Y=s.symbols('X Y',positive=True);ratio=s.powdenest((X*Y)**(p/2)/(X+Y)**p,force=True);normal=s.powdenest((s.sqrt(X/Y)+s.sqrt(Y/X))**(-p),force=True)
 checks=[eq('Positive homogeneous-kernel logarithmic Jacobian',s.powsimp(ratio/normal,force=True),1),eq('Beta normalization equals stated Gamma ratio',s.beta(p/2,p/2).rewrite(s.gamma),C),truth('Positive finite kernel mass and four pair options',p>0 and C.is_positive is True and wrong!=C)]
 cert=['All variables in the kernel are positive; the original f is nonnegative measurable with finite nonzero L2 norm. The logarithmic substitution is an L2 isometry. Its nonnegative integrand permits Tonelli, and Cauchy–Schwarz bounds every correlation. The kernel has exponential decay at both ends for every p>0, so its mass is finite and equals the convergent beta integral. The normalized indicator correlations converge pointwise to1 and are bounded by1, proving sharpness by dominated convergence. Expanding the squared translation defect is justified by these finite bounds. Strict positivity of the kernel forces zero defect for almost every shift. Strong continuity of L2 translations extends that to every shift; equivalently, invariance under any nonzero shift makes the function periodic, incompatible with finite nonzero integral on the whole real line. Thus equality is impossible.']
 return package(META,index,Q,opts,opts[0][0],steps,checks,cert,parameters={'shape':str(p),'normalizedCapacityKey':'homogeneous-continuous-kernel-shape:'+str(p),'purposefulCase':'The dimensionless exponent changes the logarithmic kernel shape and decay; dilation only translates logarithmic coordinates and cannot change this exponent. No new idea is claimed per shape.'})
def verify(row):
 expected=build(row['familyId'],row['instanceIndex']);assert row==expected
 return {'status':'passed-author-reconstruction-only','sourceContentHash':row['contentHash'],'checks':row['automatedChecks']}
if __name__=='__main__':
 rows=[build(FID,i) for i in range(14)];Path(sys.argv[1]).write_text(''.join(json.dumps(r,sort_keys=True,separators=(',',':'),ensure_ascii=False)+'\n' for r in rows));print('14 kernel candidates; independent review required')
